package com.huy.enterprise.alert;
import java.time.OffsetDateTime; import java.util.*; import com.huy.enterprise.common.*; import com.huy.enterprise.common.enums.*; import com.huy.enterprise.risk.*; import com.huy.enterprise.user.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor @Transactional(readOnly=true) public class AlertService{private final AlertRepository repository;private final UserRepository users;private final RiskEventRepository risks;public List<AlertResponse> all(){return repository.findAll().stream().map(AlertResponse::from).toList();}public AlertResponse one(UUID id){return AlertResponse.from(get(id));}@Transactional public AlertResponse create(CreateAlertRequest r){Alert a=new Alert();a.setTitle(r.title());a.setMessage(r.message());a.setAlertType(r.alertType());a.setPriority(r.priority()==null?AlertPriority.MEDIUM:r.priority());a.setStatus(AlertStatus.NEW);a.setRecipientUser(r.recipientUserId()==null?null:users.findById(r.recipientUserId()).orElseThrow(()->new ResourceNotFoundException("User not found: "+r.recipientUserId())));a.setRiskEvent(r.riskEventId()==null?null:risks.findById(r.riskEventId()).orElseThrow(()->new ResourceNotFoundException("Risk event not found: "+r.riskEventId())));return AlertResponse.from(repository.save(a));}@Transactional public AlertResponse status(UUID id,AlertStatus next){Alert a=get(id);AlertStatus current=a.getStatus();boolean allowed=current==next||(current==AlertStatus.NEW&&(next==AlertStatus.READ||next==AlertStatus.RESOLVED))||(current==AlertStatus.READ&&next==AlertStatus.RESOLVED);if(!allowed)throw new BusinessException("Invalid alert status transition: "+current+" -> "+next);a.setStatus(next);if(next==AlertStatus.RESOLVED)a.setResolvedAt(OffsetDateTime.now());return AlertResponse.from(repository.save(a));}private Alert get(UUID id){return repository.findById(id).orElseThrow(()->new ResourceNotFoundException("Alert not found: "+id));}}
